class UserError(Exception):
    """A clean user-facing error."""


class EffectiveHookDestinationChanged(UserError):
    """The effective repo-scoped hook plan no longer matches the bound plan."""

    code = "effective_hook_destination_changed"


class EffectiveHookConfigurationUnverified(UserError):
    """The effective repo-scoped hook plan could not be proved safely."""

    code = "effective_hook_configuration_unverified"


class UnsupportedGitVersion(UserError):
    """The fixed Git runtime cannot satisfy the helper's safety contract."""

    code = "unsupported_git_version"


class GitVersionProbeError(UserError):
    """The bounded Git version probe did not establish a compatible version."""

    code = "git_version_probe_failed"


class UnsupportedPlatform(UserError):
    """The host platform cannot satisfy the helper's safety contract."""

    code = "unsupported_platform"


class JournalLimitExceeded(UserError):
    """Journal syntax or validation exceeded a declared semantic budget."""

    code = "journal_semantic_limit_exceeded"


class GeneratedIndexInspectionError(UserError):
    """A possible generated-index marker could not be classified safely."""

    code = "generated_index_inspection_failed"

    def __init__(
        self,
        message: str,
        *,
        error_number: int | None = None,
    ) -> None:
        if error_number is not None:
            self.errno = error_number
        super().__init__(message)


class GeneratedIndexInspectionLimitExceeded(GeneratedIndexInspectionError):
    """A possible generated-index marker exceeded its inspection budget."""

    code = "generated_index_inspection_limit_exceeded"

    def __init__(
        self,
        message: str,
        *,
        limit_name: str,
        limit: int,
        observed: int,
    ) -> None:
        self.limit_name = limit_name
        self.limit = limit
        self.observed = observed
        super().__init__(message)


class DiscoveryAuxiliaryInspectionError(UserError):
    """A discovery-only auxiliary file could not be inspected safely."""

    code = "discovery_auxiliary_inspection_failed"

    def __init__(
        self,
        message: str,
        *,
        error_number: int | None = None,
    ) -> None:
        if error_number is not None:
            self.errno = error_number
        super().__init__(message)


class DiscoveryAuxiliaryInspectionLimitExceeded(DiscoveryAuxiliaryInspectionError):
    """A discovery-only auxiliary file exceeded its inspection budget."""

    code = "discovery_auxiliary_inspection_limit_exceeded"

    def __init__(
        self,
        message: str,
        *,
        limit_name: str,
        limit: int,
        observed: int,
    ) -> None:
        self.limit_name = limit_name
        self.limit = limit
        self.observed = observed
        super().__init__(message)


class DiscoveryLimitExceeded(UserError):
    """Session discovery exceeded a declared aggregate resource budget."""

    code = "discovery_limit_exceeded"

    def __init__(self, limit_name: str, limit: int, observed: int) -> None:
        self.limit_name = limit_name
        self.limit = limit
        self.observed = observed
        super().__init__(
            f"repository discovery {limit_name} exceeds {limit} "
            f"(observed at least {observed})"
        )


class DiscoveryDeadlineExceeded(UserError):
    """Session discovery exhausted its one aggregate wall-clock budget."""

    code = "discovery_deadline_exceeded"


class DiscoveryRolloutParseError(UserError):
    """A non-empty rollout record could not be parsed completely."""

    code = "discovery_rollout_parse_failed"

    def __init__(
        self,
        *,
        parse_reason: str,
        record_number: int,
        byte_offset: int,
        detail: str,
    ) -> None:
        self.parse_reason = parse_reason
        self.record_number = record_number
        self.byte_offset = byte_offset
        self.detail = detail[:MAX_DISCOVERY_ERROR_DETAIL_CHARS]
        super().__init__(
            f"rollout record {record_number} at byte {byte_offset} "
            f"could not be parsed ({parse_reason}): {self.detail}"
        )


class DiscoveryRolloutInspectionError(UserError):
    """A rollout file could not be bound and read as one stable object."""

    code = "discovery_rollout_inspection_failed"

    def __init__(
        self,
        *,
        inspection_reason: str,
        path: pathlib.Path,
        detail: str,
        error_number: int | None = None,
    ) -> None:
        self.inspection_reason = inspection_reason
        self.detail = detail[:MAX_DISCOVERY_ERROR_DETAIL_CHARS]
        self.cleanup_errors: list[dict[str, Any]] = []
        if error_number is not None:
            self.errno = error_number
        super().__init__(
            f"rollout inspection failed ({inspection_reason}) for {path}: {self.detail}"
        )


class DiscoveryCwdValidationError(UserError):
    """A discovered CWD is unsafe to pass to filesystem path APIs."""

    code = "discovery_cwd_invalid"

    def __init__(self, validation_reason: str, detail: str) -> None:
        self.validation_reason = validation_reason
        self.detail = detail[:MAX_DISCOVERY_ERROR_DETAIL_CHARS]
        super().__init__(
            f"discovered CWD is invalid ({validation_reason}): {self.detail}"
        )


class RepositoryResolutionError(UserError):
    """A Git-looking discovery candidate could not be classified safely."""

    code = "repository_resolution_failed"

    def __init__(
        self,
        path: pathlib.Path,
        detail: str,
        *,
        resolution_reason: str,
        marker_kind: str | None = None,
        marker_path: pathlib.Path | None = None,
        marker_path_hint: pathlib.Path | None = None,
        marker_path_status: str | None = None,
        marker_level: int | None = None,
        marker_directory_device: int | None = None,
        marker_directory_inode: int | None = None,
        path_status: str | None = None,
        error_number: int | None = None,
    ) -> None:
        self.detail = detail[:MAX_DISCOVERY_ERROR_DETAIL_CHARS]
        self.resolution_reason = resolution_reason
        self.marker_kind = marker_kind
        self.marker_path = marker_path
        self.marker_path_hint = marker_path_hint
        self.marker_path_status = marker_path_status
        self.marker_level = marker_level
        self.marker_directory_device = marker_directory_device
        self.marker_directory_inode = marker_directory_inode
        self.path_status = path_status
        self.cleanup_errors: list[dict[str, Any]] = []
        if error_number is not None:
            self.errno = error_number
        super().__init__(f"repository resolution failed for {path}: {self.detail}")


